        .catch(function () { var a = q(); a.push(item); setQ(a); msg.value = ''; st.textContent = t.queued; })
        .then(function () { btn.disabled = false; });
    });
    [name, mail, msg, btn, st].forEach(function (x) { box.appendChild(x); });
