/* Ortak çekirdek — kabuk ve bileşenler (Falcon Ofis görünümü).
Önce tokens.css yüklenmeli. Yönler mantıksal özelliklerle yazılır (inline-start/end), RTL kendiliğinden çalışır.
Sınıflar Falcon ile aynı adlardadır; React uygulaması kendi CSS'ini koruyup yalnız tokens.css'i alabilir. */
*{box-sizing:border-box}.fc-root{font-size:calc(14px * var(--font-scale))}.fc-root{height:100%;margin:0}.fc-root{
background:radial-gradient(1200px 600px at 85% -10%,var(--glow-1),transparent 60%),radial-gradient(900px 500px at -10% 110%,var(--glow-2),transparent 60%),
linear-gradient(var(--bg-grid) 1px,transparent 1px) 0 0/40px 40px,linear-gradient(90deg,var(--bg-grid) 1px,transparent 1px) 0 0/40px 40px,var(--bg);
color:var(--text);-webkit-font-smoothing:antialiased;font-family:var(--font-ui);font-size:1rem;line-height:1.45
}
.fc-root[lang=ar]{font-family:var(--font-ar);line-height:1.6}
.fc-root[lang=ar] :is(input,textarea,select,button){font-family:var(--font-ar)}
button{font:inherit;color:inherit;cursor:pointer}
a{color:var(--accent);text-decoration:none}
a:hover{text-decoration:underline}
code,kbd,.mono{font-family:var(--font-mono);font-size:.86em}
.muted{color:var(--muted)}
.accent{color:var(--accent)}
.ltr{direction:ltr;unicode-bidi:isolate}
.fc-hidden,[hidden]{display:none!important}
svg.fc-spin{animation:fc-spin 1.1s linear infinite}
svg.fc-pulse{animation:fc-pulse 1.2s ease-in-out infinite}
svg.fc-i{width:1.15em;height:1.15em;flex:none;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
:focus-visible{outline:var(--focus-w) solid var(--focus);outline-offset:2px}
/* ---- kabuk ---- */
.shell{height:100%;display:flex}
.sidebar{width:var(--sidebar-w);flex:none;display:flex;flex-direction:column;border-inline-end:var(--border-w) solid var(--border);background:var(--sidebar-bg);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px)}
.brand{display:flex;align-items:center;gap:12px;padding:22px 20px 18px;border-bottom:var(--border-w) solid var(--border)}
.brand-logo{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:var(--grad-primary);color:var(--on-accent);flex:none}
.brand-name{font-size:1.21rem;font-weight:700;letter-spacing:.2px}
.brand-tag{color:var(--muted);margin-top:2px;font-size:.82rem}
.version-badge{color:var(--accent);direction:ltr;background:var(--accent-soft);border:1px solid var(--accent-line);border-radius:999px;align-self:flex-start;margin-inline-start:auto;padding:2px 7px;font-size:11px;font-weight:600}
.nav{flex:1;padding:12px 12px 20px;overflow-y:auto}
.nav-group{margin-top:10px}
.nav-group-title{text-transform:uppercase;letter-spacing:1.2px;color:var(--nav-title);padding:10px 12px 6px;font-size:11px}
.fc-root[lang=ar] .nav-group-title{letter-spacing:0;text-transform:none;font-size:12px}
.nav-item{display:flex;align-items:center;gap:12px;margin:2px 0;padding:10px 12px;border:1px solid transparent;border-radius:10px;color:var(--nav-text);background:none;width:100%;text-align:start;transition:background .15s,color .15s,border-color .15s}
.nav-item:hover{background:var(--panel-hover);color:var(--text);text-decoration:none}
.nav-item.active{color:var(--text);background:var(--grad-active);border-color:var(--active-line);box-shadow:inset 3px 0 0 var(--accent)}
.fc-root[dir=rtl] .nav-item.active{box-shadow:inset -3px 0 0 var(--accent)}
.nav-item.active svg{color:var(--accent)}
.main{flex:1;min-width:0;display:flex;flex-direction:column}
.content{flex:1;padding:28px 32px 40px;overflow-y:auto}
/* ---- üst çubuk ---- */
.topbar{position:relative;z-index:40;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:16px 24px 16px 32px;border-bottom:var(--border-w) solid var(--border);background:var(--topbar-bg);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}
.fc-root[dir=rtl] .topbar{padding:16px 32px 16px 24px}
.topbar-title{min-width:0}
.page-title{margin:0;font-size:1.57rem;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.page-sub{color:var(--muted);margin:4px 0 0;font-size:.93rem}
.topbar-actions{display:flex;align-items:center;gap:8px;flex-wrap:nowrap}
.topbar-sep{width:1px;height:22px;background:var(--border);margin-inline:4px}
.win-controls{display:flex;gap:6px}
.icon-btn.menu-btn{display:none}
.icon-btn{display:grid;place-items:center;width:34px;height:34px;padding:0;border:var(--border-w) solid var(--border);border-radius:9px;color:var(--muted);background:none;position:relative}
.icon-btn:hover{background:var(--panel-hover);color:var(--text)}
