.fc-small{font-size:12px}
/* ---- modal ---- */
.modal-backdrop{position:fixed;inset:0;z-index:50;display:grid;place-items:center;grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(0,1fr);padding:30px;background:var(--backdrop);-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);animation:fc-fade .15s}
