/* Baskı kaydı ürün stoğuna eklenir; birim maliyet ağırlıklı ortalama olur. */
async function addToProducts(name, qty, unitCost, location, photoId, margin) {
  name = String(name || "").trim();
  qty = Math.max(0, Math.round(nz(qty)));
  if (!name || qty <= 0) return null;

  const key = name.toLocaleLowerCase(I18N[LANG]._locale);
  let p = S.products.find(x => String(x.name || "").toLocaleLowerCase(I18N[LANG]._locale) === key);
  if (!p) p = { id: DB.uid(), name, qty: 0, unitCost: 0 };

  const oldQty = Math.max(0, nz(p.qty));
  const total = oldQty + qty;
  p.unitCost = total > 0 ? (oldQty * nz(p.unitCost) + qty * nz(unitCost)) / total : nz(unitCost);
  p.qty = total;
  if (location) p.location = location;
  if (photoId && !p.photoId) p.photoId = photoId;
  if (nz(margin) > 0) p.margin = nz(margin);

  await DB.put("products", p);
  return p.id;
}

/* ======================================================================
   SATIŞLAR
   ====================================================================== */
function sellForm(p) {
  if (!p) return;
  const stok = Math.max(0, nz(p.qty));
  modal(t("sell_title", { ad: p.name }), `
    <div class="trow"><span data-i18n="in_stock"></span><b>${stok} ${esc(t("pieces"))}</b></div>
    <div class="trow"><span data-i18n="unit_cost_one"></span><b>${esc(money(nz(p.unitCost)))}</b></div>
    <div class="pair" style="margin-top:14px">
      <div class="field"><label data-i18n="sale_qty"></label>
        <div class="inp"><input id="v_qty" type="number" min="1" max="${stok}" step="1" value="1"><span data-i18n="pieces"></span></div></div>
      <div class="field"><label data-i18n="sale_unit_price"></label>
        <div class="inp"><span>$</span><input id="v_price" type="number" min="0" step="0.01" value="${suggestedPrice(p).toFixed(2)}"></div></div>
    </div>
    <div class="pair" style="margin-top:11px">
      <div class="field"><label data-i18n="sale_date"></label>
        <div class="inp"><input id="v_date" type="date" value="${today()}"></div></div>
      <div class="field"><label data-i18n="customer"></label>
        <div class="inp"><select id="v_cust">${opts(S.customers, null, t("none"))}</select></div></div>
    </div>
    <div class="field"><label data-i18n="payment"></label>
      <div class="inp"><select id="v_pay">${PAY_KINDS.map(k =>
        `<option value="${k}"${k === "paid" ? " selected" : ""}>${esc(t("pay_" + k))}</option>`).join("")}</select></div></div>
    <div class="field"><label data-i18n="note_field"></label>
      <div class="inp"><input id="v_note"></div></div>
    <div class="totals" style="margin-top:14px">
      <div class="trow"><span data-i18n="sale_total"></span><b id="v_tot">—</b></div>
      <div class="trow strong"><span data-i18n="sale_profit"></span><b id="v_pro">—</b></div>
    </div>
  `, [
    { label: t("cancel"), onClick: closeModal },
    { label: t("sell"), kind: "pri", onClick: () => saveSale(p) }
  ]);

  const hesapla = () => {
    const q = Math.max(0, Math.round(nz($("#v_qty").value)));
    const pr = nz($("#v_price").value);
    $("#v_tot").textContent = money(q * pr);
    $("#v_pro").textContent = money(q * (pr - nz(p.unitCost)));
  };
  ["v_qty", "v_price"].forEach(id => $("#" + id).addEventListener("input", hesapla));
  hesapla();
}

async function saveSale(p) {
  const qty = Math.max(0, Math.round(nz($("#v_qty").value)));
  const price = nz($("#v_price").value);
  const stok = Math.max(0, nz(p.qty));
  if (qty <= 0) { toast(t("required"), "bad"); return; }
  if (qty > stok) { toast(t("not_enough_stock", { n: stok }), "bad"); return; }

  const custId = $("#v_cust").value || null;
  const sale = {
    id: DB.uid(),
    productId: p.id, productName: p.name,
    qty, unitPrice: price, unitCost: nz(p.unitCost),
    total: qty * price,
    cost: qty * nz(p.unitCost),
    profit: qty * (price - nz(p.unitCost)),
    date: $("#v_date").value || today(),
    customerId: custId, customerName: nameOf(S.customers, custId),
    payment: $("#v_pay").value || "paid",
    note: $("#v_note").value.trim(),
    location: p.location || ""
  };
  await DB.put("sales", sale);

  p.qty = stok - qty;                       // stoktan düş
  await DB.put("products", p);

  closeModal();
  await reload();
  S.screen = "sales";
  render();
  toast(t("sale_done"), "good");
}

function saleTotals(list) {
  return list.reduce((a, s) => {
    if (s.payment === "cancelled") return a;
    a.n += nz(s.qty); a.rev += nz(s.total); a.cost += nz(s.cost); a.profit += nz(s.profit);
    return a;
  }, { n: 0, rev: 0, cost: 0, profit: 0 });
}

function screenSales() {
  const q = (S._saleSearch || "").toLowerCase().trim();
  const list = S.sales
    .filter(s => !q || [s.productName, s.customerName, s.note].join(" ").toLowerCase().includes(q))
    .sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")));
  const tot = saleTotals(list);

  return `
  <h1 data-i18n="sales_title"></h1>
  <p class="lead" data-i18n="sales_sub"></p>

  <div class="statrow">
    <div class="stat"><em data-i18n="sold_qty"></em><b>${tot.n} ${esc(t("pieces"))}</b></div>
    <div class="stat"><em data-i18n="revenue"></em><b>${esc(money(tot.rev))}</b></div>
    <div class="stat"><em data-i18n="total_cost"></em><b>${esc(money(tot.cost))}</b></div>
    <div class="stat"><em data-i18n="total_profit"></em><b>${esc(money(tot.profit))}</b></div>
  </div>

  <div class="toolbar">
    <div class="inp"><input id="saleSearch" type="search" data-i18n-ph="search" value="${esc(S._saleSearch || "")}"></div>
    <div class="inp narrow"><select id="saleCur">${["USD", "TRY", "SYP"].map(c =>
      `<option value="${c}"${(S._recCur || S.settings.primaryCurrency) === c ? " selected" : ""}>${c}</option>`).join("")}</select></div>
  </div>

  ${list.length ? `<div class="tablewrap"><table>
    <thead><tr>
      <th data-i18n="date"></th><th data-i18n="product"></th><th data-i18n="customer"></th>
      <th class="num" data-i18n="sold_qty"></th>
      <th class="num" data-i18n="sale_unit_price"></th>
      <th class="num" data-i18n="sale_total"></th>
      <th class="num" data-i18n="sale_profit"></th>
      <th data-i18n="payment"></th><th></th>
    </tr></thead>
    <tbody>${list.map(s => `<tr>
      <td>${esc(dateStr(s.date))}</td>
      <td>${esc(s.productName || "—")}</td>
      <td>${esc(s.customerName || "—")}</td>
      <td class="num">${nz(s.qty)}</td>
      <td class="num">${esc(money(nz(s.unitPrice)))}</td>
      <td class="num">${esc(money(nz(s.total)))}</td>
      <td class="num">${esc(money(nz(s.profit)))}</td>
      <td><span class="pill ${s.payment || "paid"}">${esc(t("pay_" + (s.payment || "paid")))}</span></td>
      <td class="act"><button class="icon-btn" data-sdelete="${esc(s.id)}" title="${esc(t("remove"))}">🗑</button></td>
    </tr>`).join("")}</tbody>
  </table></div>` : `<div class="empty" data-i18n="no_sales"></div>`}`;
}

function bindSales() {
  const sr = $("#saleSearch");
  sr.oninput = e => { S._saleSearch = e.target.value; const pos = e.target.selectionStart;
    render(); const el = $("#saleSearch"); if (el) { el.focus(); el.setSelectionRange(pos, pos); } };
  $("#saleCur").onchange = e => { S._recCur = e.target.value; render(); };
  $$("[data-sdelete]").forEach(b => b.onclick = () => {
    const sale = byId(S.sales, b.dataset.sdelete);
    if (!sale) return;
    confirmBox(t("sale_delete_confirm"), async () => {
      const p = byId(S.products, sale.productId);
      if (p) { p.qty = Math.max(0, nz(p.qty)) + nz(sale.qty); await DB.put("products", p); }
      await DB.del("sales", sale.id);
      await reload(); render(); toast(t("stock_returned", { n: nz(sale.qty) }));
    });
  });
}

/* ======================================================================
   GÜNCELLEME BİLDİRİMİ
   Her program açılışında denetler; yeni sürüm varsa üstte bir şerit çıkar
   ve sekmeye nokta koyar. Şerit, güncellenene ya da "Sonra" denene kadar
   durur.
   ====================================================================== */
const UP = { found: null, busy: false };

function upBarEls() {
  return { bar: $("#upBar"), txt: $("#upBarTxt"), notes: $("#upBarNotes"),
           go: $("#upBarGo"), later: $("#upBarLater") };
}

function showUpBar(u) {
  const e = upBarEls();
  if (!e.bar) return;
  e.txt.textContent = t("update_banner", { v: u.version });
  e.notes.textContent = u.notes || "";
  e.notes.title = u.notes || "";
  e.go.textContent = t("update_now");
  e.later.textContent = t("update_later");
  e.bar.hidden = false;
  const bd = document.querySelector("#topUpd .top-badge"); if (bd) bd.hidden = false;
  document.body.classList.add("has-upbar");
  markTabDot(true);
}

function hideUpBar() {
  const e = upBarEls();
  if (e.bar) e.bar.hidden = true;
  document.body.classList.remove("has-upbar");
  markTabDot(false);
}

function markTabDot(on) {
  const btn = $('#tabs button[data-screen="settings"]');
  if (!btn) return;
  const old = $(".tabdot", btn);
  if (on && !old) {
    const i = document.createElement("i");
    i.className = "tabdot";
    btn.appendChild(i);
  } else if (!on && old) old.remove();
}

/* loud: kullanıcı düğmeye bastı — sonucu her hâlükârda bildir. */
async function checkUpdates(loud) {
  const st = await DB.getSettings();
  const status = $("#upStatus");

  if (!st.ghOwner || !st.ghRepo) {
    if (loud && status) { status.className = "status err"; status.textContent = t("up_no_channel"); }
    return null;
  }
  if (UP.busy) return null;
  UP.busy = true;
  if (loud && status) { status.className = "status"; status.textContent = t("update_checking"); }

  try {
    const u = await SYNC.checkUpdate();
    await DB.saveSettings({ lastUpdateCheck: DB.now() });
    S.settings = await DB.getSettings();

    if (u.available) {
      UP.found = u;
      /* "Sonra" denen sürümü tekrar tekrar göstermeyiz; daha yenisi gelirse gösteririz */
      if (S.settings.skipVersion && SYNC.cmpVer(u.version, S.settings.skipVersion) <= 0) {
        if (loud) showUpBar(u);
      } else {
        showUpBar(u);
        if (!loud) toast(t("update_banner", { v: u.version }), "good");
      }
      if (status) {
        status.className = "status ok";
        status.textContent = t("update_found", { v: u.version }) + (u.notes ? " — " + u.notes : "");
      }
    } else {
      UP.found = null;
      hideUpBar();
      if (status) {
        status.className = "status ok";
        status.textContent = t("up_to_date");
      }
    }
    if (S.screen === "settings") paintUpdateStatusLine();
    return u;
  } catch (e) {
    if (status) { status.className = "status err"; status.textContent = t("update_fail", { msg: e.message }); }
    if (loud) toast(t("update_fail", { msg: e.message }), "bad");
    return null;
  } finally {
    UP.busy = false;
  }
}

async function applyFoundUpdate() {
  if (!UP.found) return;
  const u = UP.found;
  const status = $("#upStatus");
  const e = upBarEls();
  if (e.go) { e.go.disabled = true; e.go.textContent = t("update_applying"); }
  if (status) { status.className = "status"; status.textContent = t("update_applying"); }
  try {
    if (!u.release) {
      const goster = p => {
        const yz = IndirmeIlerleme.yazi(p, LANG);
        if (status) status.textContent = yz;
        if (e.txt) e.txt.textContent = t("update_banner", { v: u.version }) + " — " + yz;
      };
      u.release = await SYNC.downloadRelease(u.size, goster);
      if (status) status.textContent = t("update_applying");
    }
    await DB.saveSettings({ justUpdatedTo: u.version, skipVersion: null });
    const done = await SYNC.applyUpdate(u.release);
    if (status) status.textContent = t("update_done");
    setTimeout(() => window.shell.restart(), 500);
    if (!done) toast(t("update_done"), "good");
  } catch (err) {
    await DB.saveSettings({ justUpdatedTo: null });
    if (e.go) { e.go.disabled = false; e.go.textContent = t("update_now"); }
    if (status) { status.className = "status err"; status.textContent = t("update_fail", { msg: err.message }); }
    toast(t("update_fail", { msg: err.message }), "bad");
  }
}

function paintUpdateStatusLine() {
  const el = $("#upLastCheck");
  if (!el) return;
  const st = S.settings;
  el.textContent = st.lastUpdateCheck
    ? t("update_last_check", { time: new Date(st.lastUpdateCheck).toLocaleTimeString(I18N[LANG]._locale) })
    : t("update_never_checked");
}

/* ======================================================================
   YÖNLENDİRME
   ====================================================================== */
const SCREENS = {
  calc:     { html: screenCalc,     bind: bindCalc },
  records:  { html: screenRecords,  bind: bindRecords },
  products: { html: screenProducts, bind: bindProducts },
  sales:    { html: screenSales,    bind: bindSales },
  printers: { html: screenPrinters, bind: bindPrinters },
  cats:     { html: screenCats,     bind: bindCats },
  stock:    { html: screenStock,    bind: bindStock },
  reports:  { html: screenReports,  bind: bindReports },
  settings: { html: screenSettings, bind: bindSettings }
};

function bindRecords() {
  $("#bNewRec").onclick = () => openRecordForm(null, null);
  $("#fCur").onchange = e => { S._recCur = e.target.value; paintRecords(); };
  ["fSearch", "fPrinter", "fCustomer", "fPay", "fFrom", "fTo"].forEach(id => {
    const el = $("#" + id);
    el.addEventListener("input", paintRecords);
    el.addEventListener("change", paintRecords);
  });
  if (S._pendingPrinter) { $("#fPrinter").value = S._pendingPrinter; S._pendingPrinter = null; }
  paintRecords();
}

function render() {
  const sc = SCREENS[S.screen] || SCREENS.calc;
  $("#main").innerHTML = sc.html();
  applyI18n($("#main"));
  $$("#tabs button").forEach(b => b.classList.toggle("on", b.dataset.screen === S.screen));
  if (UP.found && $("#upBar") && !$("#upBar").hidden) showUpBar(UP.found);
  else markTabDot(false);
  try { sc.bind(); } catch (e) { console.error(e); }
  window.scrollTo(0, 0);
}

/* ======================================================================
   AÇILIŞ
   ====================================================================== */
async function boot() {
  if (window.shellReady) { try { await window.shellReady; } catch (e) {} }
  await DB.openDB();
  S.settings = await DB.getSettings();

  /* ilk açılışta örnek kategoriler: boş ekranla karşılaşmasın */
  if (!(await DB.all("filaments")).length && !(await DB.all("printers")).length) {
    const pla = { id: DB.uid(), name: "PLA", price: 20, color: "#45C8BE" };
    const prn = { id: DB.uid(), name: "Ender 3", watt: 150, price: 400, life: 5000 };
    await DB.putMany("filaments", [
      pla,
      { id: DB.uid(), name: "PETG", price: 24, color: "#6C9BF0" },
      { id: DB.uid(), name: "ABS", price: 22, color: "#F0876A" }
    ]);
    await DB.put("printers", prn);
    /* ilk hesap boş seçimle açılmasın */
    await DB.saveSettings({ defFilamentId: pla.id, defPrinterId: prn.id });
  }

  await reload();
  setLang(S.settings.lang || "tr");
  $("#verTag").textContent = "v" + window.APP_VERSION;
  $("#langSel").value = S.settings.lang || "tr";

  $("#langSel").onchange = async e => {
    await DB.saveSettings({ lang: e.target.value });
    S.settings = await DB.getSettings();
    setLang(e.target.value);
    render();
  };
  $$("#tabs button").forEach(b => b.onclick = () => { S.screen = b.dataset.screen; render(); });
  $("#modalX").onclick = closeModal;
  $("#modalWrap").onclick = e => { if (e.target.id === "modalWrap") closeModal(); };
  document.addEventListener("keydown", e => { if (e.key === "Escape") closeModal(); });

  render();

  /* sağ üst düğmeler */
  const upBtn = $("#topUpd"), syBtn = $("#topSync");
  const topTitles = () => { upBtn.title = t("top_update"); syBtn.title = t("top_sync");
    upBtn.setAttribute("aria-label", upBtn.title); syBtn.setAttribute("aria-label", syBtn.title); };
  topTitles();
  $("#langSel").addEventListener("change", topTitles);
  upBtn.onclick = async () => {
    upBtn.classList.add("busy");
    try {
      const u = UP.found || await checkUpdates(true);
      if (u && u.available) await applyFoundUpdate();
      else if (u) toast(t("up_to_date"), "good");
    } finally { upBtn.classList.remove("busy"); }
  };
  syBtn.onclick = async () => {
    syBtn.classList.add("busy");
    try { await doSync(true); } finally { syBtn.classList.remove("busy"); }
  };

  /* bildirim şeridinin düğmeleri */
  $("#upBarGo").onclick = () => applyFoundUpdate();
  $("#upBarLater").onclick = async () => {
    if (UP.found) await DB.saveSettings({ skipVersion: UP.found.version });
    S.settings = await DB.getSettings();
    hideUpBar();
  };

  /* güncelleme sonrası ilk açılış: ne yüklendiğini söyle */
  if (S.settings.justUpdatedTo) {
    const v = S.settings.justUpdatedTo;
    await DB.saveSettings({ justUpdatedTo: null });
    S.settings = await DB.getSettings();
    setTimeout(() => toast(t("update_applied", { v }), "good"), 600);
  }

  if (S.settings.fullscreen) window.shell.setFullscreen(true);
  if (S.settings.autoRates) doFetchRates(false);

  /* güncelleme denetimi Firebase'den bağımsız; eşitleme ayrı */
  if (S.settings.autoUpdate) checkUpdates(false);
  if (S.settings.fb && S.settings.fb.projectId) doSync().catch(() => {});
}

document.addEventListener("DOMContentLoaded", boot);
